INSERT INTO "public"."sentences" ("id", "created_at", "japanese_text", "kana_text", "english_translation", "audio_prompt_url", "jlpt_level", "category") VALUES
	('0344b513-08b9-425c-a87b-554c1a5bfc16', '2026-06-28 23:59:48.101744+00', '今日は思ったより早く仕事が終わったので、久しぶりに友達と食事に行くことにした。', 'きょうはおもったよりはやくしごとがおわったので、ひさしぶりにともだちとしょくじにいくことにした。', 'Work ended earlier than I expected today, so I decided to go out to eat with a friend for the first time in a while.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_dc_meeting_with_friend.mp3', 'N2', 'daily_conversation'),
	('3632ea24-13da-4064-9353-2e2a675a111a', '2026-06-28 23:59:48.101744+00', '最近は忙しくて運動する時間が取れなかったから、体力が落ちた気がする。', 'さいきんはいそがしくてうんどうするじかんがとれなかったから、たいりょくがおちたきがする。', 'I have been so busy lately that I have not had time to exercise, so I feel like my stamina has declined.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_dc_busy_grown_weaker.mp3', 'N2', 'daily_conversation'),
	('432e80fe-ef9b-4ea2-809b-f30aad682d84', '2026-06-28 23:59:48.101744+00', 'もし都合がよければ、来週のどこかで一緒に昼ご飯でも食べませんか。', 'もしつごうがよければ、らいしゅうのどこかでいっしょにひるごはんでもたべませんか。', 'If it works for you, would you like to have lunch together sometime next week?', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n3/n3_dc_eat_out_invitation.mp3', 'N3', 'daily_conversation'),
	('55a9ac7f-cc8e-4880-9f12-534e85991235', '2026-06-28 23:59:48.101744+00', '昨日は夜遅くまで起きていたせいで、朝なかなか起きられなかった。', 'きのうはよるおそくまでおきていたせいで、あさなかなかおきられなかった。', 'Because I stayed up late last night, I had a hard time getting up in the morning.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n3/n3_dc_stay_up_late.mp3', 'N3', 'daily_conversation'),
	('6634615d-63bc-4689-9722-b32e652e46ca', '2026-06-28 23:59:48.101744+00', '電車が遅れていたおかげで、かえって余裕を持って準備することができた。', 'でんしゃがおくれていたおかげで、かえってよゆうをもってじゅんびすることができた。', 'Thanks to the train being delayed, I actually had extra time to get ready.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_dc_late_train_blessing.mp3', 'N2', 'daily_conversation'),
	('9940250a-4375-45fe-9a50-534fe790cdeb', '2026-06-28 23:59:48.101744+00', '初めて会ったとは思えないほど話が弾んで、とても楽しい時間を過ごした。', 'はじめてあったとはおもえないほどはなしがはずんで、とてもたのしいじかんをすごした。', 'The conversation flowed so naturally that it did not feel like we had just met, and I had a really enjoyable time.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_dc_first_time_meeting.mp3', 'N2', 'daily_conversation'),
	('27480f9b-8342-478a-9ec1-e28e1517ecde', '2026-06-28 23:59:48.101744+00', 'どちらを選んでも大きな違いはないと思うので、自分の直感を信じてみたらどうですか。', 'どちらをえらんでもおおきなちがいはないとおもうので、じぶんのちょっかんをしんじてみたらどうですか。', 'I do not think there is a big difference whichever one you choose, so why not trust your own intuition?', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_dc_believe_in_intuiton.mp3', 'N2', 'daily_conversation'),
	('bfad8c91-4afa-4d34-8b96-c50410aaca19', '2026-06-28 23:59:48.101744+00', '最近引っ越したばかりなので、この辺りのことはまだよく分からない。', 'さいきんひっこしたばかりなので、このあたりのことはまだよくわからない。', 'I just moved here recently, so I still do not know this area very well.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n3/n3_dc_just_moved.mp3', 'N3', 'daily_conversation'),
	('298b4145-4d79-4517-bb70-a2d02315602e', '2026-06-28 23:59:48.101744+00', '何か困ったことがあったら遠慮せずに相談してください。', 'なにかこまったことがあったらえんりょせずにそうだんしてください。', 'If you have any problems, please feel free to ask me for advice.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n3/n3_dc_ask_for_advice.mp3', 'N3', 'daily_conversation'),
	('1f3dac96-4dff-46be-8b43-4d876a34b7da', '2026-06-28 23:59:48.101744+00', 'せっかくの機会だから、新しいことにも積極的に挑戦してみたい。', 'せっかくのきかいだから、あたらしいことにもせっきょくてきにちょうせんしてみたい。', 'Since this is a valuable opportunity, I want to actively try new things as well.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_dc_try_new_things.mp3', 'N2', 'daily_conversation'),
	('df22d76b-dff5-439d-be7d-c3bdfaa03a75', '2026-06-29 00:15:54.244294+00', '今回のプロジェクトでは、チーム全体の連携が成功の鍵になると考えています。', 'こんかいのプロジェクトでは、チームぜんたいのれんけいがせいこうのかぎになるとかんがえています。', 'For this project, I believe coordination across the entire team will be the key to success.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_key_to_success.mp3', 'N2', 'Workplace'),
	('ea29471f-0fe7-4de4-9c27-204f4678dccd', '2026-06-29 00:15:54.244294+00', '会議で指摘された課題について、改めて検討する必要があります。', 'かいぎでしてきされたかだいについて、あらためてけんとうするひつようがあります。', 'We need to reexamine the issues that were pointed out during the meeting.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_discussion_needed.mp3', 'N2', 'Workplace'),
	('62b8de5c-5c20-4a93-8171-cb5da829f9e9', '2026-06-29 00:15:54.244294+00', '納期に間に合わせるためには、優先順位を見直さなければなりません。', 'のうきにまにあわせるためには、ゆうせんじゅんいをみなおさなければなりません。', 'To meet the deadline, we need to reconsider our priorities.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_reconsider_order.mp3', 'N2', 'Workplace'),
	('4184c3bf-dd15-4d85-ada4-956955256cbe', '2026-06-29 00:15:54.244294+00', '現時点では十分なデータがそろっていないため、結論を出すのは難しいです。', 'げんじてんではじゅうぶんなデータがそろっていないため、けつろんをだすのはむずかしいです。', 'At this point, we don''t have enough data, so it''s difficult to reach a conclusion.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_cannot_make_conclusion.mp3', 'N2', 'Workplace'),
	('33bbdbac-9b61-42f6-89c8-34bff5589d66', '2026-06-29 00:15:54.244294+00', 'ご提案いただいた内容については、社内で共有したうえで検討いたします。', 'ごていあんいただいたないようについては、しゃないできょうゆうしたうえでけんとういたします。', 'We will review your proposal after sharing it internally.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_workplace_investigate_sharing.mp3', 'N1', 'Workplace'),
	('0258a045-f30c-484a-bdb8-a20f866f87e2', '2026-06-29 00:15:54.244294+00', '問題の原因を特定するまでに予想以上の時間がかかりました。', 'もんだいのげんいんをとくていするまでによそういじょうのじかんがかかりました。', 'It took longer than expected to identify the cause of the problem.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_determine_problem_cause.mp3', 'N2', 'Workplace'),
	('ab973a28-acb0-4c84-a68d-03213642e619', '2026-06-29 00:15:54.244294+00', '関係部署との調整が必要なので、回答まで少々お時間をいただければ幸いです。', 'かんけいぶしょとのちょうせいがひつようなので、かいとうまでしょうしょうおじかんをいただければさいわいです。', 'We need to coordinate with the relevant department, so we would appreciate a little more time before responding.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_workplace_coordinate.mp3', 'N1', 'Workplace'),
	('2b34b425-a6da-4ce4-ac20-1cd04304373e', '2026-06-29 00:15:54.244294+00', 'この機能を実装することで、業務効率の向上が期待できます。', 'このきのうをじっそうすることで、ぎょうむこうりつのこうじょうがきたいできます。', 'Implementing this feature is expected to improve work efficiency.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_improve_efficiency.mp3', 'N2', 'Workplace'),
	('d86a2e20-e73b-4dc4-99dd-d5cef8dd1d31', '2026-06-29 00:15:54.244294+00', '想定外のトラブルが発生したものの、大きな影響はありませんでした。', 'そうていがいのトラブルがはっせいしたものの、おおきなえいきょうはありませんでした。', 'Although an unexpected issue occurred, it did not have a major impact.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_no_effect.mp3', 'N2', 'Workplace'),
	('fd59b3fe-74c7-4a33-bd15-51cc355bd3c7', '2026-06-29 00:15:54.244294+00', '今後の方針については、来週の会議で正式に決定する予定です。', 'こんごのほうしんについては、らいしゅうのかいぎでせいしきにけっていするよていです。', 'Our future policy will be formally decided at next week''s meeting.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_workplace_determine_next_week.mp3', 'N2', 'Workplace'),
	('074c84cc-19c4-4808-8c54-fb0e30953842', '2026-06-29 00:26:16.782757+00', '政府は来年度の予算案について最終的な調整を進めている。', 'せいふはらいねんどのよさんあんについてさいしゅうてきなちょうせいをすすめている。', 'The government is making final adjustments to next fiscal year''s budget proposal.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_fiscal_year.mp3', 'N2', 'News'),
	('03e91117-a74a-42a3-8d44-d5b6203e7b0b', '2026-06-29 00:26:16.782757+00', '専門家によると、景気の回復にはまだ時間がかかる可能性があるという。', 'せんもんかによると、けいきのかいふくにはまだじかんがかかるかのうせいがあるという。', 'According to experts, it may still take time for the economy to recover.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_economy_recovery.mp3', 'N2', 'News'),
	('f7cd5c8a-1004-4c3d-9ac4-31592936cd75', '2026-06-29 00:26:16.782757+00', '新しい制度の導入に対して、さまざまな意見が寄せられている。', 'あたらしいせいどのどうにゅうにたいして、さまざまないけんがよせられている。', 'Various opinions have been expressed regarding the introduction of the new system.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_new_system_opinions.mp3', 'N2', 'News'),
	('a773b9e8-e858-48a3-b0f4-d141c9e3e5bb', '2026-06-29 00:26:16.782757+00', '世界的な需要の増加により、価格の上昇が続いている。', 'せかいてきなじゅようのぞうかにより、かかくのじょうしょうがつづいている。', 'Prices continue to rise due to increasing global demand.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_price_rises.mp3', 'N2', 'News'),
	('5ee48413-caaa-4824-81da-69b992c9ba3b', '2026-06-29 00:26:16.782757+00', '環境問題への関心は年々高まっている。', 'かんきょうもんだいへのかんしんはねんねんたかまっている。', 'Interest in environmental issues is growing year by year.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n3/n3_news_environment_interest.mp3', 'N3', 'News'),
	('58fbd777-48b9-42be-9290-733012703822', '2026-06-29 00:26:16.782757+00', '地域経済の活性化を目的とした新たな取り組みが始まった。', 'ちいきけいざいのかっせいかをもくてきとしたあらたなとりくみがはじまった。', 'A new initiative aimed at revitalizing the local economy has begun.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_local_economies.mp3', 'N2', 'News'),
	('4b65f439-ea3f-410e-9031-0562d75f286d', '2026-06-29 00:26:16.782757+00', '調査結果によれば、多くの人が将来に不安を感じていることが分かった。', 'ちょうさけっかによれば、おおくのひとがしょうらいにふあんをかんじていることがわかった。', 'Survey results showed that many people feel anxious about the future.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_survey_results.mp3', 'N2', 'News'),
	('10d7094b-5721-4c7d-b80e-9979f04c9922', '2026-06-29 00:26:16.782757+00', '災害への備えの重要性が改めて認識されている。', 'さいがいへのそなえのじゅうようせいがあらためてにんしきされている。', 'The importance of disaster preparedness has once again been recognized.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_disaster_preparedness.mp3', 'N2', 'News'),
	('e6df3093-97c0-459b-9a66-169ed8752695', '2026-06-29 00:26:16.782757+00', '技術革新によって私たちの生活は大きく変化しつつある。', 'ぎじゅつかくしんによってわたしたちのせいかつはおおきくへんかしつつある。', 'Technological innovation is significantly changing our lives.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_news_tech_innovations.mp3', 'N2', 'News'),
	('d028d729-abc3-41bb-a6cb-44381f70affc', '2026-06-29 00:26:16.782757+00', '政策の効果については、今後も慎重に検証していく必要がある。', 'せいさくのこうかについては、こんごもしんちょうにけんしょうしていくひつようがある。', 'The effectiveness of the policy will need to be carefully evaluated going forward.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_news_evaluate_policies.mp3', 'N1', 'News'),
	('920de39f-09db-49a5-98f5-2a27ee311943', '2026-06-21 14:38:16.028267+00', 'この小説は心の機微をよく表現できている。', 'このしょうせつはこころのきびをよくひょうげんできている。', 'This novel expresses the subtle nuances of human feelings well.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_novel_feelings.mp3', 'N1', 'General'),
	('b51b06fb-56b7-4d38-8a59-cc13e2fb80c4', '2026-06-29 00:36:39.676505+00', '個人的には、その考え方には賛成できる部分もあれば疑問に思う部分もある。', 'こじんてきには、そのかんがえかたにはさんせいできるぶぶんもあればぎもんにおもうぶぶんもある。', 'Personally, there are aspects of that way of thinking that I agree with, and others that I question.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_opinions_agree_disagree.mp3', 'N1', 'Opinions'),
	('1454c5c9-6355-4155-9e2f-d5d132484294', '2026-06-29 00:36:39.676505+00', '短期的な利益だけでなく、長期的な視点から判断することが重要だ。', 'たんきてきなりえきだけでなく、ちょうきてきなしてんからはんだんすることがじゅうようだ。', 'It is important to make decisions from a long-term perspective, not just based on short-term gains.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_opinions_decision_perspective.mp3', 'N1', 'Opinions'),
	('473114ed-6c83-4f02-8e1d-8b22a10e7d0a', '2026-06-29 00:36:39.676505+00', '必ずしも全員が同じ意見を持つ必要はないと思う。', 'かならずしもぜんいんがおなじいけんをもつひつようはないとおもう。', 'I don''t think everyone necessarily needs to share the same opinion.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_opinions_diverse_opinions.mp3', 'N2', 'Opinions'),
	('ff250ba4-6457-4e22-84cf-0850be270b1d', '2026-06-29 00:36:39.676505+00', '問題を解決するためには、まず現状を正しく理解することが欠かせない。', 'もんだいをかいけつするためには、まずげんじょうをただしくりかいすることがかかせない。', 'To solve a problem, it is essential to first understand the current situation correctly.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_opinions_understand_problem.mp3', 'N2', 'Opinions'),
	('ea797373-aff4-4988-b897-fc0b51354413', '2026-06-29 00:36:39.676505+00', '他人の意見に耳を傾けることで、新たな発見が得られることもある。', 'たにんのいけんにみみをかたむけることで、あらたなはっけんがえられることもある。', 'Listening to other people''s opinions can sometimes lead to new discoveries.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_opinions_listen_to_others.mp3', 'N2', 'Opinions'),
	('6acf5607-3741-4eb8-818a-4697d917aca2', '2026-06-29 00:36:39.676505+00', '失敗を恐れて何もしないより、挑戦して学ぶほうが価値がある。', 'しっぱいをおそれてなにもしないより、ちょうせんしてまなぶほうがかちがある。', 'It is more valuable to challenge yourself and learn than to do nothing out of fear of failure.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_opinions_learn_from_challenges.mp3', 'N2', 'Opinions'),
	('ac6fe37e-68f6-4eaa-b951-a4ee8860d433', '2026-06-29 00:36:39.676505+00', 'どんな選択にもメリットとデメリットが存在する。', 'どんなせんたくにもメリットとデメリットがそんざいする。', 'Every choice has both advantages and disadvantages.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_opinions_pros_cons_choices.mp3', 'N2', 'Opinions'),
	('5813d563-3052-4b31-9dbe-f62edd89e282', '2026-06-29 00:36:39.676505+00', '理想を追い求めることも大切だが、現実とのバランスも考えなければならない。', 'りそうをおいもとめることもたいせつだが、げんじつとのバランスもかんがえなければならない。', 'Pursuing ideals is important, but we must also consider the balance with reality.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_opinions_balance_of_ideals.mp3', 'N1', 'Opinions'),
	('46a8ad0b-46c9-4343-aedb-e7b784b36b01', '2026-06-29 00:36:39.676505+00', '一つの出来事を異なる視点から見ることで、理解が深まることがある。', 'ひとつのできごとをことなるしてんからみることで、りかいがふかまることがある。', 'Looking at an event from different perspectives can deepen your understanding.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_opinions_deeper_understanding.mp3', 'N2', 'Opinions'),
	('b4874d4d-715b-45e9-9277-2bd02e2a130c', '2026-06-29 00:36:39.676505+00', '経験を積むにつれて、自分の価値観も少しずつ変化していく。', 'けいけんをつむにつれて、じぶんのかちかんもすこしずつへんかしていく。', 'As you gain experience, your values gradually change as well.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n2/n2_opinions_gain_experience.mp3', 'N2', 'Opinions'),
	('140982f8-391d-4438-b766-d0357de77d2d', '2026-06-29 00:47:40.339254+00', '情報があふれている現代社会では、何が正しいのかを自分で判断する力が求められている。', 'じょうほうがあふれているげんだいしゃかいでは、なにがただしいのかをじぶんではんだんするちからがもとめられている。', 'In today''s information-saturated society, people are expected to have the ability to judge for themselves what is correct.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_judge_information.mp3', 'N1', 'Advanced'),
	('543a829e-29be-400d-a7d9-da57f86f63de', '2026-06-29 00:47:40.339254+00', '技術の進歩は私たちの生活を便利にする一方で、新たな課題も生み出している。', 'ぎじゅつのしんぽはわたしたちのせいかつをべんりにするいっぽうで、あらたなかだいもうみだしている。', 'While technological progress makes our lives more convenient, it also creates new challenges.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_tech_advances.mp3', 'N1', 'Advanced'),
	('440cf4f9-4012-435c-be65-22d5bea2cd59', '2026-06-29 00:47:40.339254+00', '国際化が進む中で、多様な価値観を理解し尊重する姿勢がこれまで以上に重要になっている。', 'こくさいかがすすむなかで、たようなかちかんをりかいしそんちょうするしせいがこれまでいじょうにじゅうようになっている。', 'As globalization advances, the attitude of understanding and respecting diverse values has become more important than ever.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_globalization_values.mp3', 'N1', 'Advanced'),
	('245bac22-ee60-4ec9-b3e2-d462c052e186', '2026-06-29 00:47:40.339254+00', '教育の目的は単に知識を身につけることではなく、自ら考える力を育てることにある。', 'きょういくのもくてきはたんにちしきをみにつけることではなく、みずからかんがえるちからをそだてることにある。', 'The purpose of education is not merely to acquire knowledge, but to cultivate the ability to think independently.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_education_purpose.mp3', 'N1', 'Advanced'),
	('5d66a1d3-c95d-434e-9770-f89f26db832a', '2026-06-29 00:47:40.339254+00', '環境問題は一国だけで解決できるものではなく、国際的な協力が不可欠である。', 'かんきょうもんだいはいっこくだけでかいけつできるものではなく、こくさいてきなきょうりょくがふかけつである。', 'Environmental issues cannot be solved by one country alone; international cooperation is indispensable.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_environmental_issues.mp3', 'N1', 'Advanced'),
	('877162f7-bd52-4de8-b064-58f595337f93', '2026-06-29 00:47:40.339254+00', '社会の変化に対応するためには、継続的に学び続ける姿勢が求められる。', 'しゃかいのへんかにたいおうするためには、けいぞくてきにまなびつづけるしせいがもとめられる。', 'To adapt to changes in society, a commitment to lifelong learning is required.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_lifelong_learning.mp3', 'N1', 'Advanced'),
	('0fe41bc1-e130-4be2-a636-e48652f323dc', '2026-06-29 00:47:40.339254+00', 'インターネットの普及によって情報へのアクセスは容易になったが、その信頼性を見極める必要がある。', 'インターネットのふきゅうによってじょうほうへのアクセスはよういになったが、そのしんらいせいをみきわめるひつようがある。', 'The spread of the internet has made access to information easier, but it is necessary to determine its reliability.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_info_reliability.mp3', 'N1', 'Advanced'),
	('81e25a6a-6468-41ef-94d3-8d4d2ef44b79', '2026-06-29 00:47:40.339254+00', '人工知能の発展は多くの可能性を秘めている一方で、倫理的な課題も指摘されている。', 'じんこうちのうのはってんはおおくのかのうせいをひめているいっぽうで、りんりてきなかだいもしてきされている。', 'While the development of artificial intelligence holds great potential, ethical concerns have also been raised.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_ai_advancements.mp3', 'N1', 'Advanced'),
	('94d3b0c6-3191-41c8-b56b-1e7ee470fe51', '2026-06-29 00:47:40.339254+00', 'グローバル化が進展するにつれて、異文化間のコミュニケーション能力の重要性が高まっている。', 'グローバルかがしんてんするにつれて、いぶんかかんのコミュニケーションのうりょくのじゅうようせいがたかまっている。', 'As globalization progresses, the importance of cross-cultural communication skills continues to increase.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_cross_cultural_comunication.mp3', 'N1', 'Advanced'),
	('572fde4a-f665-48ec-b469-1eaf40810548', '2026-06-29 00:47:40.339254+00', '持続可能な社会を実現するためには、個人と企業の双方が責任を果たす必要がある。', 'じぞくかのうなしゃかいをじつげんするためには、こじんときぎょうのそうほうがせきにんをはたすひつようがある。', 'To achieve a sustainable society, both individuals and companies must fulfill their responsibilities.', 'https://chycityeoaprvneuoxkd.supabase.co/storage/v1/object/public/audio/jlpt_n1/n1_advanced_responsibilities_society.mp3', 'N1', 'Advanced');
